export const deriveSameOrderbookPriceBandBounds = (anchor: bigint): Readonly<{
    minAllowed: bigint;
    maxAllowed: bigint;
}> => {
    if (anchor <= 0n)
        throw new Error('ORDERBOOK_PRICE_BAND_ANCHOR_INVALID');
    const offset = (anchor * BigInt(SWAP_CONSTANTS.PRICE_REJECT_BPS)) /
        BigInt(SWAP_CONSTANTS.BPS_BASE);
    return { minAllowed: anchor - offset, maxAllowed: anchor + offset };
};

